public class DoubleCheck {
  static boolean a(double m, double med) { return Math.abs(m - med) / med * 100 <= 5; }
  static boolean b(double m, double med) { return Math.abs(m - med) * 100 <= 5 * med; }
  static boolean c(double m, double med) { return 100 * Math.abs(m / med - 1) <= 5; }
  public static void main(String[] x) {
    double m = 3.15, med = 3.0;
    System.out.println("claimed case med=3 m=3.15 (exactly +5%, so all should be true)");
    System.out.println("  |m-med|/med*100 = " + (Math.abs(m - med) / med * 100) + " -> passes? " + a(m, med));
    System.out.println("  |m-med|*100 <= 5*med: " + (Math.abs(m - med) * 100) + " vs " + (5 * med) + " -> passes? " + b(m, med));
    System.out.println("  100*|m/med-1|: " + (100 * Math.abs(m / med - 1)) + " -> passes? " + c(m, med));
    // search exact +5% and -5% boundaries (decimal-exact) where double formulations give the wrong answer
    Random r = new Random(1);
    int na = 0, nb = 0, nc = 0, total = 0;
    List<String> exA = new ArrayList<>(), exB = new ArrayList<>();
    for (int i = 0; i < 200000; i++) {
