      long k = (r.nextInt(5000) + 5) * 20L;      // med in cents, multiple of 20 => 1.05*med exact in cents
      BigDecimal med1 = BigDecimal.valueOf(k, 2);
      for (BigDecimal f : new BigDecimal[]{new BigDecimal("1.05"), new BigDecimal("0.95")}) {
        BigDecimal m1 = med1.multiply(f);
