        if (m1.subtract(med1).abs().multiply(BigDecimal.valueOf(100)).compareTo(med1.multiply(BigDecimal.valueOf(5))) != 0) continue;
        total++;
        double dm = m1.doubleValue(), dmed = med1.doubleValue();
        if (!a(dm, dmed)) { na++; if (exA.size() < 3) exA.add(med1 + " / " + m1); }
        if (!b(dm, dmed)) { nb++; if (exB.size() < 3) exB.add(med1 + " / " + m1); }
        if (!c(dm, dmed)) nc++;
      }
    }
    System.out.println("exact boundary cases tried: " + total);
    System.out.println("  (a) |m-med|/med*100 <= 5 wrongly EXCLUDES: " + na + " e.g. " + exA);
    System.out.println("  (b) |m-med|*100 <= 5*med wrongly EXCLUDES: " + nb + " e.g. " + exB);
    System.out.println("  (c) 100*|m/med-1| <= 5 wrongly EXCLUDES: " + nc);
  }
}
