    @Test
    void aSingleSurvivorIsNotAFailure() {
        Screened s = withStaticPed(snapshot(bookAtMid("A", "100"), crossedAtMid("X", "100")));

        assertThat(survivorNames(s)).containsExactly("A");
        assertThat(s.excludedExchanges()).containsExactly("X");
    }
}

